frappe.db.get_list('Site', {
    fields: ['name', 'site_type', 'disabled'], 
    limit: 0, 
    order_by: 'creation desc'
}).then(sites => {

    let html = styles + `
        <div class="env-wrapper">
            <div class="env-header-bar">
                <div style="font-weight: bold; color: #4b5563; padding-left: 15px; font-size: 16px; display: flex; align-items: center; gap: 10px;">
                    🏢 Site Management <span style="font-size: 12px; font-weight: normal; background: white; padding: 2px 8px; border-radius: 10px;">${sites.length} Total</span>
                </div>
                <div style="display: flex; gap: 10px; align-items: center;">
                    <input type="text" id="site-search" class="env-search" placeholder="Search sites 🔍">
                    <button class="env-action-btn" id="add-site-btn">+ Add New Site</button>
                </div>
            </div>

            <div class="env-filter-container">
                <button class="env-filter-btn active" data-filter="All">All Sites</button>
                <button class="env-filter-btn" data-filter="Permanent">Permanent</button>
                <button class="env-filter-btn" data-filter="Temporary">Temporary</button>
                <button class="env-filter-btn" data-filter="Disabled">Disabled</button>
            </div>

            <div class="env-grid">
    `;

    if (sites.length === 0) {
        html += `<div style="grid-column: 1 / -1; text-align: center; padding: 40px; color: #64748b;">No sites found. Click "+ Add New Site" to create one.</div>`;
    } else {
        sites.forEach(site => {
            // Logic: Is it disabled? If not, is it permanent or temporary?
            let badge_class = 'badge-unknown';
            let display_status = 'Unknown';
            let filter_status = 'Unknown';

            if (site.disabled === 1) {
                badge_class = 'badge-disabled';
                display_status = 'Disabled';
                filter_status = 'Disabled';
            } else if (site.site_type === 'Permanent Site') {
                badge_class = 'badge-permanent';
                display_status = 'Permanent';
                filter_status = 'Permanent';
            } else if (site.site_type === 'Temporary Site') {
                badge_class = 'badge-temporary';
                display_status = 'Temporary';
                filter_status = 'Temporary';
            }

            html += `
                <div class="env-card" data-site="${site.name}" data-status="${filter_status}">
                    <span class="env-badge ${badge_class}">${display_status}</span>
                    <div class="env-site-icon">🏢</div>
                    <div class="env-title" title="${site.name}">${site.name}</div>
                    <div class="env-subtitle">Click to view details</div>
                </div>
            `;
        });
    }

    html += `</div></div>`;
    root_element.innerHTML = html;

    // 3. ATTACH CLICK LISTENERS
    root_element.querySelector('#add-site-btn').addEventListener('click', () => frappe.new_doc('Site'));

    root_element.querySelectorAll('.env-card').forEach(card => {
        card.addEventListener('click', function() {
            frappe.set_route('Form', 'Site', this.getAttribute('data-site'));
        });
    });

    // 4. THE SMART FILTERING ENGINE
    const searchInput = root_element.querySelector('#site-search');
    const filterBtns = root_element.querySelectorAll('.env-filter-btn');

    function applyFilters() {
        const searchTerm = searchInput.value.toLowerCase();
        const activeFilter = root_element.querySelector('.env-filter-btn.active').getAttribute('data-filter');

        root_element.querySelectorAll('.env-card').forEach(card => {
            const title = card.querySelector('.env-title').innerText.toLowerCase();
            const status = card.getAttribute('data-status');

            const matchesSearch = title.includes(searchTerm);
            const matchesStatus = (activeFilter === 'All' || status === activeFilter);

            card.style.display = (matchesSearch && matchesStatus) ? 'block' : 'none';
        });
    }

    if (searchInput) {
        searchInput.addEventListener('keydown', e => e.stopPropagation());
        searchInput.addEventListener('input', e => {
            e.stopPropagation();
            applyFilters();
        });
    }

    filterBtns.forEach(btn => {
        btn.addEventListener('click', function() {
            filterBtns.forEach(b => b.classList.remove('active'));
            this.classList.add('active');
            applyFilters();
        });
    });
});

