// 2. FETCH QUOTATIONS (Pulling live data from ERPNext)
frappe.db.get_list('Quotation', {
    fields: ['name', 'transaction_date', 'customer_name', 'status', 'owner'],
    limit: 100, // Fetch the latest 100 quotes to build the table and stats
    order_by: 'creation desc'
}).then(quotes => {

    // --- CALCULATE PERFORMANCE STATS DYNAMICALLY ---
    let userStats = {};

    quotes.forEach(q => {
        let user = q.owner;
        // Strip the email domain to get just the username for display (e.g., 'midhul' from 'midhul@enviro.com')
        let displayName = user.split('@')[0].toUpperCase(); 

        if (!userStats[displayName]) {
            userStats[displayName] = { made: 0, won: 0, pending: 0, lost: 0, initial: displayName.charAt(0) };
        }

        userStats[displayName].made++;

        if (q.status === 'Ordered') {
            userStats[displayName].won++;
        } else if (q.status === 'Lost' || q.status === 'Cancelled') {
            userStats[displayName].lost++;
        } else {
            userStats[displayName].pending++;
        }
    });

    // --- BUILD THE HTML ---
    let html = styles + `
        <div class="sales-dashboard">
            <div class="enviro-nav">
                <div class="nav-buttons">
                    <button class="nav-pill active" id="btn-quote-register">Quote Register</button>
                    <button class="nav-pill highlight" id="btn-generate">Generate Quote</button>
                </div>
            </div>

            <div class="table-container">
                <table class="enviro-table">
                    <thead>
                        <tr>
                            <th>Quote No</th>
                            <th>Date</th>
                            <th>Customer</th>
                            <th>Sales Person</th>
                            <th>Status</th>
                            <th>Action</th>
                        </tr>
                    </thead>
                    <tbody>
    `;

    if (quotes.length === 0) {
        html += `<tr><td colspan="6">No quotations found.</td></tr>`;
    } else {
        // Build table rows
        quotes.forEach(q => {
            // Determine badge color based on standard ERPNext status
            let badgeClass = 'badge-draft';
            if (q.status === 'Open' || q.status === 'Replied') badgeClass = 'badge-open';
            if (q.status === 'Ordered') badgeClass = 'badge-ordered';
            if (q.status === 'Lost' || q.status === 'Cancelled') badgeClass = 'badge-lost';

            // Format Date safely
            let formattedDate = frappe.datetime.str_to_user(q.transaction_date);

            html += `
                <tr>
                    <td style="font-weight: bold; color: #0ea5e9;">${q.name}</td>
                    <td>${formattedDate}</td>
                    <td>${q.customer_name || 'N/A'}</td>
                    <td>${q.owner.split('@')[0]}</td>
                    <td><span class="status-badge ${badgeClass}">${q.status}</span></td>
                    <td>
                        <button class="btn-action view" data-name="${q.name}">View</button>
                        <button class="btn-action delete" data-name="${q.name}">Delete</button>
                    </td>
                </tr>
            `;
        });
    }

    html += `
                    </tbody>
                </table>
            </div>

            <h5 style="margin-top: 10px; font-weight: bold; color: #333;">Sales Performance (Latest 100)</h5>
            <div class="performance-cards">
    `;

    // Build the User Cards dynamically based on the math we did above
    Object.keys(userStats).forEach(user => {
        let stats = userStats[user];
        html += `
            <div class="card user-card">
                <div class="avatar">${stats.initial}</div>
                <div class="stats">
                    <p class="stat-blue">Total Quote Made: ${stats.made}</p>
                    <p class="stat-blue">Total Quote Won: ${stats.won}</p>
                    <p class="stat-orange">Total Quote Pending: ${stats.pending}</p>
                    <p class="stat-red">Total Quote Lost: ${stats.lost}</p>
                </div>
                <div class="name-tag">${user}</div>
            </div>
        `;
    });

    html += `
            </div>
        </div>
    `;

    // Inject the final HTML
    root_element.innerHTML = html;

    // --- 3. ATTACH CLICK LISTENERS (Routing) ---

    // Generate Quote Button
    root_element.querySelector('#btn-generate').addEventListener('click', () => {
        frappe.new_doc('Quotation'); // Native ERPNext routing for new doc!
    });

    // View Buttons
    root_element.querySelectorAll('.btn-action.view').forEach(btn => {
        btn.addEventListener('click', function() {
            let quoteName = this.getAttribute('data-name');
            frappe.set_route('Form', 'Quotation', quoteName); // Opens the specific quote
        });
    });

    // Delete Buttons (With safety confirmation prompt)
    root_element.querySelectorAll('.btn-action.delete').forEach(btn => {
        btn.addEventListener('click', function() {
            let quoteName = this.getAttribute('data-name');

            frappe.confirm(`Are you sure you want to delete ${quoteName}?`,
                () => {
                    // If user clicks Yes
                    frappe.client.delete('Quotation', quoteName).then(() => {
                        frappe.show_alert({message: 'Quotation Deleted', indicator: 'green'});
                        // Refresh the workspace to update the table
                        frappe.ui.toolbar.clear_cache();
                    });
                }, () => {
                    // If user clicks No, do nothing
                }
            );
        });
    });

